/**
 * Cache the value of the select as it can get lost in option updates.
 *
 * @type {string}
 */
#cachedValue;

get value() {
  return this.select.value;
}

set value(newValue) {
  // Cache the value in case we need to restore it.
  this.#cachedValue = newValue;
  this.select.value = newValue;
}
